-- CycloneDX SBOM generated by a run's SBOM stage, gzip-compressed; one per scanned monorepo folder ('' = whole repository).
CREATE TABLE pipeline_run_sbom (
    run_id     UUID         NOT NULL REFERENCES pipeline_run (id) ON DELETE CASCADE,
    folder     VARCHAR(120) NOT NULL DEFAULT '',
    content    BYTEA        NOT NULL,
    size_bytes INT          NOT NULL,
    components INT          NOT NULL,
    created_at TIMESTAMPTZ  NOT NULL DEFAULT now(),
    PRIMARY KEY (run_id, folder)
);
